import sys; sys.path.insert(0, __import__("pathlib").Path(__file__).resolve().parents[1].as_posix())
from explications import *

ENTREES = [
    ("## 🗝️ Vocabulaire", 'fin', apropos("Une machine tombe en panne un lundi matin et bloque toute la production. Aurait-on pu l'éviter ? Comment ?", "Souvent **oui** : en entretenant la machine **avant** la panne (nettoyage, contrôle visuel, remplacement d'une pièce usée). C'est la **maintenance préventive**.\n\nDans cette séance, tu apprends ce qu'un technicien débutant (niveau N1) peut faire : **nettoyer**, **observer**, **protéger les composants** contre l'électricité statique et **noter** son intervention.")),
    ("## 1.", 'fin', clair("La maintenance est classée en **niveaux** selon la difficulté. Retiens l'idée : **plus le niveau est élevé, plus l'intervenant est spécialisé**.\n\n- **N1** : gestes simples (nettoyer, vérifier, régler) ;\n- **N2** : échange de pièces standard ;\n- **N3** : diagnostic de pannes complexes ;\n- **N4** : révision générale, reconstruction.\n\nIl existe aussi deux façons d'intervenir : **avant** la panne (**préventive**) ou **après** (**corrective**).") + "\n" + verifie(
        ("Nettoyer une carte avec un pinceau antistatique : quel niveau de maintenance ?", "**N1** : c'est une opération simple de proximité."),
        ("Remplacer un condensateur qui a gonflé après une panne : préventif ou correctif ?", "**Correctif** : on intervient **après** l'apparition de la panne."),
        ("Quel est l'avantage de la maintenance préventive ?", "Elle **réduit les pannes imprévues** et les arrêts non planifiés.")) + "\n" + retenir("N1 à N4 : du simple au spécialisé.", "Préventive = avant la panne ; corrective = après la panne.")),
    ("## 2.", 'fin', clair("Une carte **poussiéreuse** chauffe mal et peut créer des **courts-circuits** (la poussière retient l'humidité). On la nettoie **hors tension**, avec les **bons produits** :\n\n- **pinceau antistatique** pour la poussière ;\n- **air comprimé ESD** pour souffler ;\n- **isopropanol (IPA)** et chiffon **non pelucheux** pour les traces de flux.\n\nOn n'utilise **jamais d'eau**.") + "\n" + verifie(
        ("Pourquoi nettoie-t-on la carte hors tension ?", "Pour éviter un **court-circuit** ou une **électrocution**, et protéger les composants."),
        ("Quel produit dissout les résidus de flux ?", "L'**isopropanol (IPA)**."),
        ("Pourquoi utilise-t-on un chiffon non pelucheux ?", "Pour ne pas laisser de **fibres** sur la carte.")) + "\n" + retenir("Hors tension, avec un pinceau antistatique, de l'air comprimé ESD et de l'IPA.")),
    ("## 3.", 'fin', clair("Avant de toucher à quoi que ce soit, **regarde** : le diagnostic visuel permet de trouver beaucoup de pannes **sans instrument**. Il suit une **check-list de 9 critères** : propreté, composants, brasures, condensateurs, pistes, connecteurs, traces de chaleur, corps des composants, repères.\n\nLe réflexe : **observer, noter, puis agir**.") + "\n" + verifie(
        ("Un condensateur électrolytique a le dessus bombé. Que faut-il en conclure ?", "Il est **défectueux** (il a gonflé) : il faut le **remplacer**, en respectant la polarité."),
        ("Une brasure est mate et granuleuse. Que fait-on ?", "C'est une **brasure froide** : on la **refait**."),
        ("Pourquoi commencer par un diagnostic visuel ?", "Parce qu'il est **rapide, gratuit** et ne risque pas d'endommager la carte.")) + "\n" + retenir("Observer avant d'agir ; 9 critères visuels.")),
    ("## 4.", 'fin', clair("Quand tu marches sur de la moquette puis que tu touches une poignée, tu reçois une **étincelle** : c'est une **décharge électrostatique** (ESD). Toi, tu ne sens que les décharges **supérieures à 3 000 V**. Un composant, lui, peut être détruit **dès 100 V**. Tu peux donc **détruire un composant sans rien sentir**.\n\nLa protection : **te mettre au même potentiel que la carte** (bracelet relié à la terre), travailler sur un **tapis antistatique**, ranger les pièces dans des **sachets antistatiques**.") + "\n" + verifie(
        ("Pourquoi une décharge ESD peut-elle détruire un composant sans qu'on la sente ?", "Parce que l'homme ne ressent qu'au-dessus d'environ **3 000 V**, alors qu'un composant peut être détruit **dès 100 V**."),
        ("Qu'est-ce qu'un dommage latent ?", "Une **dégradation invisible** : le composant fonctionne encore, mais tombera en panne **plus tard**."),
        ("Cite deux équipements de protection ESD.", "Le **bracelet antistatique** relié à la terre et le **tapis antistatique** (ainsi que les sachets argentés).")) + "\n" + erreurs("Toucher les broches d'un composant sans protection.", "Ranger une carte dans un sachet plastique ordinaire : il charge la carte en électricité statique.") + "\n" + retenir("Tu peux détruire un composant sans rien sentir.", "Bracelet relié à la terre, tapis, sachets antistatiques.")),
    ("## 5.", 'fin', clair("Chaque outil a un **rôle précis** : brucelle (saisir de petites pièces), pince coupante (couper les pattes), loupe (voir les défauts), multimètre (mesurer), tournevis **isolés** (sécurité), bracelet ESD (protéger les composants). **Utiliser le bon outil** évite d'abîmer la carte.") + "\n" + verifie(
        ("Pourquoi utilise-t-on des tournevis isolés ?", "Pour **éviter un court-circuit** ou un contact avec une partie sous tension."),
        ("À quoi sert la loupe ?", "À **inspecter** les brasures et les pistes (fissures, ponts, soudures froides).")) ),
    ("## 6.", 'fin', clair("La **fiche d'intervention** est la **trace écrite** de ton travail : **ce que tu as observé**, **ce que tu as fait**, **ce qui reste à faire**. Sans elle, personne ne sait ce qui a été réalisé. Elle sert aussi de **preuve** pour le suivi du matériel.") + "\n" + verifie(
        ("Pourquoi remplit-on une fiche d'intervention ?", "Pour **garder une trace** : constats, actions réalisées et suites à donner, afin que le suivi soit possible.")) + "\n" + retenir("Écrire ce qu'on observe, ce qu'on fait et ce qui reste à faire.")),
]
